import type { CurriculumTrack } from "./curriculum";

export type SchoolForm = 1 | 2 | 3 | 4;

export type SchoolLessonDefinition = {
  id: string;
  sequence: number;
  form: SchoolForm;
  curriculum: CurriculumTrack;
  title: string;
  topic: string;
  objectives: string[];
  sections: { label: string; title: string; body: string; highYield: string }[];
  reference: string;
  bankFocus: string[];
  bankTopics: string[];
  bankKeywords: string[];
};

const lesson = (
  id: string, sequence: number, form: SchoolForm, title: string, topic: string,
  objectives: string[], sections: SchoolLessonDefinition["sections"],
  bankTopics: string[], bankKeywords: string[], bankFocus: string[],
): SchoolLessonDefinition => ({
  id, sequence, form, curriculum: "high-school", title, topic, objectives, sections,
  reference: "Kenyan secondary-school Biology study scope", bankTopics, bankKeywords, bankFocus
});

export const HIGH_SCHOOL_LESSONS: SchoolLessonDefinition[] = [
  lesson("hs-f1-introduction",1,1,"Introduction to Biology","Form 1 • Biology Foundations",
    ["Define Biology and identify major branches.","Explain the characteristics of living organisms and distinguish observation, inference and conclusion.","Describe basic biological skills, laboratory safety and responsible handling of specimens."],
    [
      {label:"01 • Meaning",title:"What is Biology?",body:"Biology is the scientific study of living organisms and their life processes. It examines organisms from microscopic structures and cells to whole organisms, populations and ecosystems. The word Biology is commonly traced to Greek bios (life) and logos (study).",highYield:"Biology is the scientific study of living organisms and life processes."},
      {label:"02 • Branches",title:"Branches of Biology",body:"Botany deals with plants and zoology with animals. Other branches include microbiology, anatomy, physiology, ecology, genetics, taxonomy, cytology and biochemistry. A branch is defined by the aspect of life it investigates.",highYield:"Know the branch from the object or process being studied."},
      {label:"03 • Importance",title:"Why study Biology?",body:"Biology supports health care, agriculture, environmental conservation, nutrition, biotechnology, veterinary work, education and many other careers. It also develops observation, measurement, classification, communication and problem-solving skills.",highYield:"Link Biology to health, agriculture, environment, food and scientific careers."},
      {label:"04 • Characteristics",title:"Characteristics of living organisms",body:"Living organisms carry out nutrition, respiration, gaseous exchange, excretion, growth, movement, sensitivity and reproduction. Growth is a permanent increase in size or dry mass, while reproduction produces new individuals.",highYield:"Learn the characteristics together and understand what each process means."},
      {label:"05 • Scientific skills",title:"Observation and measurement",body:"Biological investigations require careful observation, accurate measurement, recording of results, comparison and interpretation. An observation is evidence obtained through the senses or instruments; an inference is an explanation based on evidence.",highYield:"Do not confuse an observation with an explanation or conclusion."},
      {label:"06 • Investigation",title:"Variables and fair tests",body:"A fair investigation changes the independent variable, measures the dependent variable and controls relevant variables. A hypothesis is a testable proposed explanation. Results should be recorded clearly before conclusions are drawn.",highYield:"Independent = changed, dependent = measured, controlled = kept constant."},
      {label:"07 • Laboratory safety",title:"Working safely",body:"Handle specimens, glassware, chemicals and biological materials carefully. Wear appropriate protective equipment, label materials, keep the work area clean and report accidents immediately. Never taste laboratory substances.",highYield:"Safety is part of good scientific practice, not an optional extra."},
      {label:"08 • Quick check",title:"Before the RAT",body:"Revise definitions, branches, characteristics of life, scientific skills, variables, hypotheses and basic laboratory safety.",highYield:"Be able to explain a Biology idea, not merely name it."}
    ],["Biology Foundations","Scientific Method"],["biology","living organisms","characteristics","scientific method","observation","hypothesis","laboratory"],["Meaning and branches","Characteristics of life","Scientific investigation","Laboratory safety"]),

  lesson("hs-f1-classification",2,1,"Classification I","Form 1 • Classification",
    ["Explain why organisms are classified and identified.","Use observable features and a simple dichotomous key.","Describe the hierarchy of classification and principles of scientific naming."],
    [
      {label:"01 • Need",title:"Why classify organisms?",body:"Classification groups organisms according to shared characteristics. It makes identification easier, organizes biological knowledge and helps scientists communicate about organisms consistently.",highYield:"Classification is based on similarities and differences."},
      {label:"02 • Specimen study",title:"Observe before naming",body:"A specimen should be observed systematically. Useful features may include body form, presence of appendages, leaf arrangement, venation, symmetry and other observable characteristics.",highYield:"Record observable evidence before deciding the group."},
      {label:"03 • Magnifying lens",title:"Using a hand lens",body:"A magnifying lens helps reveal small external features that may not be obvious to the unaided eye. Hold specimens safely and use good lighting while comparing structures.",highYield:"Magnification helps observation; it does not replace careful description."},
      {label:"04 • Hierarchy",title:"Taxonomic ranks",body:"The traditional hierarchy moves from broad groups to narrower groups: kingdom, phylum or division, class, order, family, genus and species. Each lower rank contains fewer, more closely related organisms.",highYield:"Species is narrower than genus; genus is narrower than family."},
      {label:"05 • Scientific names",title:"Binomial nomenclature",body:"A scientific name uses two parts: the genus name followed by the specific epithet. The genus begins with a capital letter and the specific epithet with a lower-case letter when written in standard form.",highYield:"Two-part scientific names reduce confusion caused by local names."},
      {label:"06 • Major groups",title:"Broad biological groups",body:"Traditional school classification introduces groups such as Monera, Protoctista, Fungi, Plantae and Animalia. Modern biological classification has been refined by later evidence, but these school-level groups remain useful for understanding the historical classification framework.",highYield:"Use the classification system specified by the question or syllabus context."},
      {label:"07 • Identification keys",title:"Dichotomous keys",body:"A dichotomous key presents paired contrasting statements. At each step, choose the statement that matches the observed specimen and follow its indicated path until an identification is reached.",highYield:"Never skip a step or choose a feature that was not observed."},
      {label:"08 • Quick check",title:"Classification practice",body:"Practise distinguishing organisms from their observable features, arranging taxonomic ranks and following a simple key.",highYield:"Classification questions reward precise comparison."}
    ],["Classification","Taxonomy"],["classification","taxonomic","organism","kingdom","phylum","genus","species","identification key","binomial"],["Need for classification","Taxonomic hierarchy","Scientific naming","Identification keys"]),

  lesson("hs-f1-cell",3,1,"The Cell","Form 1 • Cell Biology",
    ["Describe the structure and functions of common cell organelles.","Use the light microscope safely and correctly.","Explain cell specialization and organization into tissues, organs and systems."],
    [
      {label:"01 • Cell theory",title:"The cell as a basic unit",body:"The cell is the basic structural and functional unit of living organisms. Organisms may consist of one cell or many cells. In multicellular organisms, cells can become specialized for particular roles.",highYield:"Cell structure and function are closely related."},
      {label:"02 • Microscope",title:"The light microscope",body:"A light microscope uses lenses to produce a magnified image. Main parts include the eyepiece, objective lenses, stage, diaphragm, light source, coarse adjustment and fine adjustment. Handle it carefully and begin focusing with the low-power objective.",highYield:"Start with low power, centre the specimen, then move to higher power."},
      {label:"03 • Animal cell",title:"Common cell structures",body:"A typical animal cell has a cell membrane, cytoplasm, nucleus, mitochondria, ribosomes and other structures. The membrane regulates exchange while the nucleus contains genetic material.",highYield:"Know both the structure and function of each named organelle."},
      {label:"04 • Plant cell",title:"Plant-cell adaptations",body:"Typical plant cells have a cellulose cell wall, chloroplasts and a large permanent vacuole in addition to common cell structures. Chloroplasts contain chlorophyll for photosynthesis, while the vacuole helps maintain turgor.",highYield:"Cell wall, chloroplast and large vacuole are key plant-cell features."},
      {label:"05 • Organelles",title:"Structure linked to function",body:"Mitochondria are associated with aerobic respiration, ribosomes with protein synthesis, chloroplasts with photosynthesis and the nucleus with control and genetic information. The cytoplasm is the site of many metabolic reactions.",highYield:"Use structure → function when answering organelle questions."},
      {label:"06 • Cell size",title:"Magnification and actual size",body:"Magnification compares image size with actual size. Actual size = image size ÷ magnification. Convert units carefully, especially between millimetres, micrometres and nanometres.",highYield:"Always check units before calculating actual size."},
      {label:"07 • Specialization",title:"Specialized cells",body:"Cells become specialized through differentiation. Examples include root hair cells for absorption, red blood cells for oxygen transport and palisade cells for photosynthesis. Their structures reflect their functions.",highYield:"Explain specialization using a specific structural adaptation."},
      {label:"08 • Organization",title:"From cells to systems",body:"Similar cells form tissues; tissues combine to form organs; organs work together in organ systems. This organization allows multicellular organisms to perform complex functions efficiently.",highYield:"Cell → tissue → organ → organ system → organism."}
    ],["Cell Biology"],["cell","cell structure","organelle","plant cell","animal cell","microscope","magnification","specialization","tissue","organ"],["Microscope","Cell structures","Magnification","Specialized cells","Organization"]),

  lesson("hs-f1-cell-physiology",4,1,"Cell Physiology","Form 1 • Cell Physiology",
    ["Explain movement of substances across cell membranes.","Distinguish diffusion, osmosis and active transport.","Predict effects of concentration and water-potential differences on cells."],
    [
      {label:"01 • Membrane",title:"The cell membrane",body:"The cell membrane forms a selectively permeable boundary around the cell. It controls movement of substances between the cell and its surroundings and helps maintain suitable internal conditions.",highYield:"Selective permeability means some substances cross more easily than others."},
      {label:"02 • Diffusion",title:"Movement down a gradient",body:"Diffusion is the net movement of particles from a region of higher concentration to a region of lower concentration due to random molecular motion. It does not require cellular energy.",highYield:"Diffusion moves down a concentration gradient and is passive."},
      {label:"03 • Factors",title:"What affects diffusion?",body:"Diffusion is affected by the concentration gradient, temperature, surface area and diffusion distance. A larger gradient, larger surface area and shorter distance generally increase the rate.",highYield:"Relate every factor to how frequently particles move across the surface."},
      {label:"04 • Osmosis",title:"Movement of water",body:"Osmosis is the net movement of water molecules through a selectively permeable membrane from a region of higher water potential to lower water potential.",highYield:"Osmosis concerns water and requires a selectively permeable membrane."},
      {label:"05 • Plant cells",title:"Turgid and plasmolysed cells",body:"Water entering a plant cell can make it turgid because the cell wall resists excessive expansion. Loss of water can make the membrane pull away from the wall, a condition called plasmolysis.",highYield:"Turgor supports non-woody plant tissues."},
      {label:"06 • Animal cells",title:"Effects on animal cells",body:"Animal cells lack a cellulose cell wall. In dilute surroundings they may gain water and burst, while in concentrated surroundings they lose water and become shrunken.",highYield:"Without a cell wall, animal cells are more vulnerable to extreme water movement."},
      {label:"07 • Active transport",title:"Moving against a gradient",body:"Active transport moves substances from lower concentration to higher concentration using energy supplied by the cell and membrane transport proteins. It allows cells to accumulate substances even when diffusion would oppose entry.",highYield:"Active transport requires energy and can move against a concentration gradient."},
      {label:"08 • Practical work",title:"Investigating cell physiology",body:"Potato cylinders or similar plant tissue can be used to investigate osmosis. Keep variables such as size, time and temperature controlled, measure mass or length before and after treatment, and interpret the pattern.",highYield:"A valid experiment changes one factor and measures a clear response."}
    ],["Cell Physiology"],["cell physiology","cell membrane","diffusion","osmosis","active transport","water potential","turgor","plasmolysis"],["Cell membrane","Diffusion","Osmosis","Active transport","Practical investigations"]),

  lesson("hs-f1-nutrition",5,1,"Nutrition in Plants and Animals","Form 1 • Nutrition in Plants and Animals",
    ["Explain types and importance of nutrition.","Describe photosynthesis and factors affecting its rate.","Identify major food substances, enzymes, balanced diets and basic mammalian digestion."],
    [
      {label:"01 • Nutrition",title:"Meaning and types",body:"Nutrition is the acquisition and use of nutrients for energy, growth, repair and maintenance. Autotrophs manufacture organic food from simpler substances, while heterotrophs obtain organic nutrients from other organisms or their products.",highYield:"Autotrophic nutrition makes organic food; heterotrophic nutrition obtains it."},
      {label:"02 • Leaf",title:"The leaf as a photosynthetic organ",body:"A typical leaf has a broad surface for light capture, a thin lamina for short diffusion distances, stomata for gas exchange and vascular tissues for transport. Palisade cells contain many chloroplasts.",highYield:"Leaf structure is adapted for photosynthesis and gas exchange."},
      {label:"03 • Photosynthesis",title:"Manufacturing food",body:"Green plants use light energy to convert carbon dioxide and water into glucose, releasing oxygen. Chlorophyll absorbs light energy. Glucose can be used in respiration or converted to starch and other substances.",highYield:"Carbon dioxide + water → glucose + oxygen, using light energy and chlorophyll."},
      {label:"04 • Photosynthesis investigations",title:"Testing a leaf",body:"Starch in a leaf can be tested using iodine solution after appropriate preparation. Destarching helps remove previously stored starch. Experiments can investigate the roles of light, carbon dioxide or chlorophyll while controlling other variables.",highYield:"Iodine turns blue-black when starch is present."},
      {label:"05 • Food substances",title:"Chemicals of life",body:"Carbohydrates provide energy, proteins are needed for growth and repair, and lipids provide concentrated energy and form important cell structures. Water and mineral salts are also essential for healthy organisms.",highYield:"Know both the food substance and its biological role."},
      {label:"06 • Food tests",title:"Identifying food substances",body:"Iodine solution tests for starch. Benedict's solution can test for reducing sugars after heating. Biuret reagent tests for protein, while an emulsion test can indicate lipids. Positive tests should be described by their colour change.",highYield:"Remember reagent + procedure + positive result."},
      {label:"07 • Enzymes",title:"Biological catalysts",body:"Enzymes are biological catalysts that speed up chemical reactions without being used up. Their activity is affected by temperature and pH. Very high temperatures can denature many enzymes by altering their active sites.",highYield:"Enzyme activity depends on suitable conditions."},
      {label:"08 • Animals",title:"Heterotrophic nutrition",body:"Animals obtain nutrients by feeding. Modes include holozoic nutrition, in which food is ingested and digested internally. Mammalian teeth are adapted to functions such as cutting, tearing and grinding.",highYield:"Relate tooth shape to its feeding function."},
      {label:"09 • Digestion",title:"Breaking food down",body:"Digestion breaks large, insoluble food molecules into smaller, soluble molecules that can be absorbed. In humans, digestion begins in the mouth and continues through the alimentary canal with the help of mechanical and chemical processes.",highYield:"Digestion makes food molecules suitable for absorption."},
      {label:"10 • Balanced diet",title:"Healthy nutrition",body:"A balanced diet supplies appropriate amounts of carbohydrates, proteins, lipids, vitamins, mineral salts, fibre and water. Requirements vary with age, activity, health and physiological state.",highYield:"A balanced diet is about suitable amounts and variety, not simply eating more."}
    ],["Plant Biology","Nutrition","Biochemistry"],["nutrition","photosynthesis","food test","carbohydrate","protein","lipid","mineral","enzyme","digestion","balanced diet","dentition"],["Types of nutrition","Photosynthesis","Food tests","Enzymes","Dentition and digestion","Balanced diet"]),
  lesson("hs-f2-gaseous-exchange",5,2,"Gaseous Exchange","Form 2 • Gaseous Exchange",
    ["Explain why organisms require gaseous exchange.","Describe gaseous exchange surfaces in plants and mammals.","Explain ventilation, diffusion gradients and adaptations for efficient exchange."],
    [
      {label:"01 • Need",title:"Why gaseous exchange is necessary",body:"Cells require gases for metabolism. Aerobic respiration uses oxygen and produces carbon dioxide, so organisms must obtain oxygen and remove carbon dioxide at suitable rates.",highYield:"Gas exchange supports cellular respiration and waste removal."},
      {label:"02 • Diffusion",title:"The basic mechanism",body:"Gases move across respiratory surfaces mainly by diffusion down concentration gradients. Maintaining a gradient is important for continued exchange.",highYield:"Gas movement is driven by concentration gradients."},
      {label:"03 • Efficient surfaces",title:"Adaptations",body:"Efficient exchange surfaces are thin, have a large area, are moist where appropriate and have a good supply of the transport medium. These features reduce resistance to diffusion.",highYield:"Thin + large surface area + maintained gradient = efficient exchange."},
      {label:"04 • Plants",title:"Gaseous exchange in leaves",body:"Leaves exchange gases through stomata and internal air spaces. Guard cells regulate stomatal openings, balancing carbon dioxide entry with water loss.",highYield:"Stomata are pores controlled by guard cells."},
      {label:"05 • Mammals",title:"The respiratory system",body:"Air passes through the nose or mouth, trachea, bronchi and bronchioles before reaching alveoli. Ventilation continually refreshes alveolar air.",highYield:"Know the pathway of air to the alveoli."},
      {label:"06 • Alveoli",title:"The gas exchange surface",body:"Alveoli provide a very large surface area and have thin walls close to capillary networks. Oxygen diffuses into blood while carbon dioxide diffuses out.",highYield:"Alveoli are adapted for rapid diffusion."},
      {label:"07 • Ventilation",title:"Maintaining the gradient",body:"Breathing moves air into and out of the lungs. Fresh air maintains concentration differences between alveolar air and the blood, supporting diffusion.",highYield:"Ventilation refreshes the diffusion gradient."},
      {label:"08 • Factors",title:"What affects exchange?",body:"Surface area, membrane thickness, concentration gradient and ventilation influence gas exchange. Damage or thickening of a respiratory surface can reduce diffusion.",highYield:"Link every factor to diffusion rate."}
    ],["Respiratory Biology","Plant Biology","Cell Biology"],["gaseous exchange","gas exchange","stomata","lungs","diffusion","respiration","alveoli"],["Diffusion","Exchange surfaces","Stomata","Alveoli","Ventilation"]),

  lesson("hs-f2-respiration",6,2,"Respiration","Form 2 • Respiration",
    ["Define cellular respiration and explain its importance.","Compare aerobic and anaerobic respiration.","Interpret simple investigations involving respiratory activity."],
    [
      {label:"01 • Meaning",title:"Respiration is cellular",body:"Respiration is a series of enzyme-controlled chemical reactions that releases usable energy from organic food molecules. It occurs in living cells.",highYield:"Respiration is not the same as breathing."},
      {label:"02 • Energy",title:"Why energy is needed",body:"Cells use energy for active transport, synthesis of molecules, growth, movement, repair and maintenance of internal organization.",highYield:"Link respiration to ATP-dependent cellular work."},
      {label:"03 • Aerobic",title:"Aerobic respiration",body:"Aerobic respiration uses oxygen and completely breaks down glucose to carbon dioxide and water while releasing substantial energy.",highYield:"Glucose + oxygen → carbon dioxide + water + energy."},
      {label:"04 • Anaerobic",title:"Respiration without oxygen",body:"Anaerobic pathways release less energy because glucose is only partially broken down. End products depend on the organism.",highYield:"Anaerobic respiration yields less energy than aerobic respiration."},
      {label:"05 • Muscles",title:"Vigorous exercise",body:"During intense exercise, oxygen delivery may temporarily fail to meet demand. Muscle cells can rely more on anaerobic respiration, producing lactic acid.",highYield:"Oxygen shortage can increase anaerobic contribution."},
      {label:"06 • Yeast",title:"Fermentation",body:"Yeast can respire anaerobically, producing ethanol and carbon dioxide. This process is used in bread making and some beverage production.",highYield:"Yeast anaerobic respiration produces ethanol and carbon dioxide."},
      {label:"07 • Respiration investigations",title:"Germinating seeds",body:"Germinating seeds are metabolically active and can be used to investigate heat or carbon dioxide production. Controls are needed for fair comparisons.",highYield:"Use controls when comparing respiratory activity."},
      {label:"08 • Breathing versus respiration",title:"Do not confuse the terms",body:"Breathing is the movement of air into and out of respiratory surfaces. Gaseous exchange is diffusion of respiratory gases, while respiration is the cellular chemical process that releases energy.",highYield:"Three distinct ideas: breathing, gas exchange and respiration."}
    ],["Cell Biology","Respiration"],["respiration","aerobic","anaerobic","energy release","ATP","glucose","fermentation"],["Aerobic respiration","Anaerobic respiration","Energy release","Practical investigations"]),

  lesson("hs-f2-transport-plants",7,2,"Transport in Plants","Form 2 • Transport",
    ["Explain absorption and movement of water and mineral ions.","Describe xylem, phloem and translocation.","Explain transpiration and factors affecting its rate."],
    [
      {label:"01 • Need",title:"Why plants transport materials",body:"Roots absorb water and mineral ions while leaves manufacture organic food. Materials must move between organs to support growth, metabolism and storage.",highYield:"Transport links roots, stems, leaves and storage organs."},
      {label:"02 • Root hairs",title:"Absorbing water",body:"Root hair cells have long extensions that increase surface area for absorption. Water enters mainly by osmosis while mineral ions may enter by diffusion or active transport.",highYield:"Root hairs are adapted for absorption."},
      {label:"03 • Xylem",title:"Water and mineral transport",body:"Xylem vessels conduct water and mineral ions from roots toward aerial parts. Their strengthened, hollow structure provides a continuous pathway.",highYield:"Xylem = water and mineral ions."},
      {label:"04 • Transpiration",title:"Water loss from leaves",body:"Transpiration is the loss of water vapour from aerial parts, mainly through stomata. It contributes to the movement of water through the plant.",highYield:"Most transpiration occurs through stomata."},
      {label:"05 • Transpiration stream",title:"Movement through xylem",body:"Evaporation from leaf surfaces creates tension that contributes to an upward pull on water columns in xylem. Root pressure can also contribute under some conditions.",highYield:"Connect evaporation at the leaf with upward water movement."},
      {label:"06 • Factors",title:"Factors affecting transpiration",body:"Light, temperature, humidity and wind can alter transpiration rate. Their effects can be explained through changes in stomatal opening and diffusion gradients.",highYield:"Explain each factor through water-vapour diffusion."},
      {label:"07 • Phloem",title:"Translocation",body:"Phloem transports assimilates such as sucrose from sources to sinks. A source produces or releases assimilates; a sink uses or stores them.",highYield:"Phloem = translocation of assimilates."},
      {label:"08 • Practical work",title:"Investigating water uptake",body:"A potometer can estimate water uptake under controlled conditions. It must be set up carefully because leaks or air spaces can affect the measurement.",highYield:"Control variables and eliminate leaks in plant-transport experiments."}
    ],["Plant Biology","Transport"],["transport in plants","xylem","phloem","transpiration","translocation","water movement","root hair"],["Root absorption","Xylem","Transpiration","Phloem","Translocation"]),

  lesson("hs-f2-transport-animals",8,2,"Transport in Animals","Form 2 • Transport",
    ["Explain why large animals require transport systems.","Describe blood components and their functions.","Explain the structure and function of the mammalian heart and blood vessels."],
    [
      {label:"01 • Need",title:"Why transport systems are needed",body:"Large multicellular organisms have cells far from exchange surfaces. Diffusion alone cannot deliver oxygen and nutrients quickly enough, so a circulatory system transports materials.",highYield:"Long diffusion distances create the need for transport systems."},
      {label:"02 • Blood",title:"A transport tissue",body:"Blood consists of plasma, red blood cells, white blood cells and platelets. Each component contributes to transport, defence or clotting.",highYield:"Know the function of every blood component."},
      {label:"03 • Plasma",title:"The fluid medium",body:"Plasma carries dissolved nutrients, hormones, carbon dioxide, urea, salts and heat around the body.",highYield:"Plasma carries dissolved substances."},
      {label:"04 • Red cells",title:"Oxygen transport",body:"Red blood cells contain haemoglobin and have adaptations that help transport oxygen efficiently, including a biconcave shape and lack of a nucleus when mature in mammals.",highYield:"Haemoglobin binds oxygen."},
      {label:"05 • White cells",title:"Defence",body:"White blood cells protect the body through processes including engulfing pathogens and producing antibodies.",highYield:"White cells are involved in immunity."},
      {label:"06 • Platelets",title:"Clotting",body:"Platelets help initiate blood clotting, reducing blood loss and helping prevent entry of pathogens through damaged vessels.",highYield:"Platelets are important for clot formation."},
      {label:"07 • Vessels",title:"Arteries, veins and capillaries",body:"Arteries carry blood away from the heart, veins return it, and capillaries form thin exchange networks between blood and tissues.",highYield:"Direction is defined relative to the heart."},
      {label:"08 • Heart",title:"Double circulation",body:"The mammalian heart has four chambers and maintains separate pulmonary and systemic circuits. The left ventricle pumps blood to the body at high pressure.",highYield:"Know chamber sequence and the two circulation circuits."}
    ],["Physiology","Blood & Immune Cells","Transport"],["blood","heart","artery","vein","capillary","circulation","haemoglobin","plasma","platelets"],["Blood","Blood vessels","Heart","Double circulation"]),

  lesson("hs-f3-reproduction",9,3,"Reproduction in Plants and Animals","Form 3 • Reproduction in Plants",["Explain the major concepts in Reproduction in Plants and Animals.","Apply biological principles to structured and scenario questions.","Interpret simple observations and investigations."],[
      {label:"01 • Form 3",title:"Purpose",body:"Reproduction produces offspring and maintains a species across generations; it differs from growth, which increases size or cell number. Asexual reproduction uses one parent without gamete fusion, while sexual reproduction involves fusion of haploid gametes to form a diploid zygote.",highYield:"Distinguish reproduction from growth and compare the two main reproductive modes."},
      {label:"02 • Form 3",title:"Asexual reproduction",body:"Asexual reproduction involves one parent and no gamete fusion, so offspring are usually genetically similar except for mutations. Examples include binary fission, budding in yeast and Hydra, and vegetative propagation through runners, bulbs, rhizomes or tubers. It is rapid but offers less variation when conditions change.",highYield:"Know the definition, examples, advantages and limitations."},
      {label:"03 • Form 3",title:"Sexual reproduction",body:"Meiosis forms haploid gametes; fertilization fuses them to form a diploid zygote, which develops through mitosis. Crossing over, independent assortment and random fertilization create genetic variation, which may help populations survive environmental change. Sexual reproduction often requires more time and energy than asexual reproduction.",highYield:"Trace gamete formation, fertilization and zygote development; connect meiosis to variation."},
      {label:"04 • Form 3",title:"Flower reproduction",body:"A typical flower has sepals, petals, stamens and carpels. Anthers produce pollen; the stigma receives it; the style connects stigma to ovary; and ovules contain the female reproductive structures. A pollen tube grows toward an ovule after compatible pollen germinates. After fertilization, the ovule develops into a seed and the ovary commonly forms a fruit.",highYield:"Identify flower structures and link them to pollination, fertilization and seed formation."},
      {label:"05 • Form 3",title:"Pollination and fertilization",body:"Pollination is pollen transfer from anther to stigma, not fertilization. Wind-pollinated flowers often have exposed anthers, feathery stigmas and abundant light pollen; insect-pollinated flowers often have conspicuous petals, scent or nectar. After pollen germination, a pollen tube carries male nuclei toward an ovule for fertilization.",highYield:"Pollination is pollen transfer; fertilization is gamete fusion. Compare pollination adaptations."},
      {label:"06 • Form 3",title:"Human reproduction",body:"Testes produce sperm and testosterone; sperm travel through the sperm ducts and mix with fluids from accessory glands. Ovaries produce ova and hormones, the oviduct is the usual site of fertilization, and the uterus supports embryo development. The male and female reproductive systems have distinct but complementary roles.",highYield:"Know organ functions, sperm pathways, ovulation and the usual site of fertilization."},
      {label:"07 • Form 3",title:"Pregnancy and placenta",body:"After fertilization, the zygote divides by mitosis and travels toward the uterus, where implantation occurs in the uterine lining. The placenta enables exchange of oxygen, nutrients, carbon dioxide and wastes between maternal and fetal blood without normally mixing the blood supplies directly. The umbilical cord connects fetus and placenta; some drugs, alcohol and nicotine can cross the placental barrier.",highYield:"Trace fertilization and implantation; explain placental exchange and its limits."},
      {label:"08 • Form 3",title:"Reproductive health",body:"Reproductive health includes physical, emotional and social wellbeing. Accurate information about puberty, menstrual health, consent, hygiene and sexually transmitted infections supports informed decisions. Condoms reduce the risk of many infections and unintended pregnancy when used correctly, while other contraceptives do not all protect against infections. Health concerns should be discussed with qualified providers.",highYield:"Distinguish contraception from STI prevention and use reliable health information."}
    ],["Reproduction in Plants and Animals"],["purpose","asexual","reproduction","sexual","reproduction","flower","reproduction","pollination","fertilization","human","reproduction","pregnancy"],["Core concepts","Applications","Practical interpretation"]),

  lesson("hs-f3-growth",10,3,"Growth and Development","Form 3 • Growth and Development",["Explain the major concepts in Growth and Development.","Apply biological principles to structured and scenario questions.","Interpret simple observations and investigations."],[
      {label:"01 • Form 3",title:"Growth and development",body:"Growth is a permanent increase in size, dry mass or cell number; development includes changes in form and function as cells specialize and organisms mature. Mitosis increases cell number, while differentiation produces specialized cells. Measurements should distinguish true growth from temporary water gain or loss.",highYield:"Define growth and development separately and explain the roles of mitosis and differentiation."},
      {label:"02 • Form 3",title:"Mitosis and cell production",body:"DNA replicates before mitosis so each chromosome has two sister chromatids. During prophase chromosomes condense, metaphase aligns them at the equator, anaphase separates sister chromatids, and telophase forms new nuclei; cytokinesis divides the cytoplasm. Mitosis usually produces two daughter cells with the same chromosome number as the parent, supporting growth and repair.",highYield:"Remember prophase, metaphase, anaphase and telophase; mitosis preserves chromosome number."},
      {label:"03 • Form 3",title:"Differentiation",body:"Differentiation is when an unspecialized cell develops structures and functions for a specific role. Cells generally contain the same genome, but express different genes. Root hair cells have extensions for absorption, xylem vessels have strengthened hollow walls for water transport, and red blood cells contain haemoglobin for oxygen transport.",highYield:"Explain specialization using a named structural adaptation and its function."},
      {label:"04 • Form 3",title:"Plant growth",body:"Plant growth occurs at meristems, where cells divide actively. Apical meristems at root and shoot tips increase length; lateral meristems can increase girth. New cells elongate and differentiate. Water supports turgor and metabolism; nitrates help build amino acids and magnesium is required for chlorophyll.",highYield:"Locate meristems and connect water, minerals, cell division and elongation to growth."},
      {label:"05 • Form 3",title:"Measuring growth",body:"Growth can be measured by height, length, leaf area, fresh mass, dry mass or cell number. Dry mass reduces errors from variable water content but requires destroying the sample. Use similar specimens, repeated measurements and consistent equipment. Growth rate equals change in measurement divided by elapsed time.",highYield:"Choose a suitable measurement, control conditions and calculate growth rate carefully."},
      {label:"06 • Form 3",title:"Growth factors",body:"Growth depends on inherited and environmental factors. Plants need suitable light, water, carbon dioxide, mineral ions, oxygen and temperature; animals are also affected by nutrition, hormones and health. A limiting factor is in shortest supply relative to demand, so increasing another factor may not improve growth until the limitation is removed.",highYield:"Separate genetic and environmental factors and explain limiting factors."},
      {label:"07 • Form 3",title:"Growth curves",body:"A growth curve plots a measurement against time. Growth may begin slowly, become rapid during active cell division and expansion, then slow as nutrients or space become limiting. Interpret axes, units, trends and plateaus before explaining a curve. A steeper slope indicates a greater rate of change.",highYield:"Read axes and units first; use slope to compare rates."},
      {label:"08 • Form 3",title:"Fair investigations",body:"A fair test changes one independent variable, measures the dependent variable and keeps relevant controls constant. Repeat measurements, calculate means and investigate anomalous results. Conclusions should answer the question using evidence; evaluation should identify limitations and practical improvements.",highYield:"Identify independent, dependent and controlled variables and support conclusions with data."}
    ],["Growth and Development"],["growth","development","mitosis","production","differentiation","plant","growth","measuring","growth","growth","factors","growth"],["Core concepts","Applications","Practical interpretation"]),

  lesson("hs-f3-coordination",11,3,"Coordination and Response","Form 3 • Coordination and Response",["Explain the major concepts in Coordination and Response.","Apply biological principles to structured and scenario questions.","Interpret simple observations and investigations."],[
      {label:"01 • Form 3",title:"Stimuli and receptors",body:"A stimulus is a detectable change, such as light, temperature, pressure or a chemical. Receptors detect particular stimuli and convert them into signals. Coordinators process information and effectors, usually muscles or glands in animals, produce a response that may secure resources, avoid danger or maintain internal conditions.",highYield:"Stimulus → receptor → coordinator → effector → response."},
      {label:"02 • Form 3",title:"Nervous coordination",body:"The central nervous system consists of the brain and spinal cord; peripheral nerves connect it to the body. Sensory neurones carry impulses from receptors toward the CNS, relay neurones connect pathways, and motor neurones carry impulses to effectors. Dendrites, axons and myelin support communication and can influence conduction speed.",highYield:"Distinguish sensory, relay and motor neurones by direction and function."},
      {label:"03 • Form 3",title:"Reflex action",body:"A reflex is a rapid, automatic response that protects the body. In a withdrawal reflex, a receptor detects harm, a sensory neurone carries an impulse to the spinal cord, a relay neurone passes it to a motor neurone, and a muscle contracts. The brain is informed, but the initial response can occur before conscious awareness.",highYield:"Trace the reflex arc in order and explain its protective value."},
      {label:"04 • Form 3",title:"Synapses",body:"At a chemical synapse, an arriving impulse causes neurotransmitter release from the presynaptic ending. The chemical diffuses across the synaptic cleft and binds receptors on the next cell, potentially triggering a new signal. Synapses help integrate and control communication; transmission across them takes time.",highYield:"Explain impulse arrival, neurotransmitter release, diffusion and receptor activation."},
      {label:"05 • Form 3",title:"Hormonal coordination",body:"Endocrine glands release hormones into blood; only target cells with suitable receptors respond. Hormonal effects are often slower but longer-lasting than nervous impulses. Insulin generally lowers blood glucose by promoting uptake and storage, while glucagon raises it by stimulating glucose release from stores. Hormone secretion commonly uses negative feedback.",highYield:"Explain target cells, insulin and glucagon, and feedback control."},
      {label:"06 • Form 3",title:"Tropisms",body:"A tropism is directional plant growth in response to a stimulus. Shoots commonly grow toward light (positive phototropism), while roots often grow with gravity (positive gravitropism). Unequal auxin distribution can make cells on opposite sides elongate at different rates, bending the organ. Tropisms help position leaves and roots effectively.",highYield:"Positive means growth toward the stimulus; negative means away from it."},
      {label:"07 • Form 3",title:"Homeostasis links",body:"Homeostasis keeps internal conditions within suitable limits despite external change. Receptors detect deviations, a control centre coordinates action and effectors respond. Negative feedback reduces the original deviation. Temperature regulation and blood-glucose control are examples; effective coordination links detection, communication and response.",highYield:"Negative feedback reverses a deviation rather than amplifying it."},
      {label:"08 • Form 3",title:"Tracing responses",body:"When analysing a response, identify the stimulus, receptor, coordinating centre, pathway, effector and final response. State whether the pathway is nervous or hormonal and explain its benefit. In experiments, distinguish the stimulus applied from the response measured and use data to justify conclusions about sensitivity or speed.",highYield:"Trace every stage and connect your explanation to evidence in the question."}
    ],["Coordination and Response"],["stimuli","receptors","nervous","coordination","reflex","action","synapses","hormonal","coordination","tropisms","homeostasis","links"],["Core concepts","Applications","Practical interpretation"]),

  lesson("hs-f3-ecology",12,3,"Ecology and the Environment","Form 3 • Ecology",["Explain the major concepts in Ecology and the Environment.","Apply biological principles to structured and scenario questions.","Interpret simple observations and investigations."],[
      {label:"01 • Form 3",title:"Ecological levels",body:"An organism is one individual; a population contains members of one species in an area; a community includes populations of different species; and an ecosystem includes the community plus its physical environment. A habitat is where an organism lives, while a niche describes its role and interactions.",highYield:"Distinguish organism, population, community, ecosystem, habitat and niche."},
      {label:"02 • Form 3",title:"Abiotic factors",body:"Abiotic factors include light, temperature, water availability, soil pH, oxygen and salinity. They affect survival, distribution and reproduction. Water availability influences plant growth, while temperature changes enzyme-controlled reaction rates. Recording relevant abiotic conditions helps explain patterns in ecological sampling.",highYield:"Link a measured environmental factor to its effect on organisms."},
      {label:"03 • Form 3",title:"Biotic interactions",body:"Competition occurs when organisms need the same limited resource; predation involves capturing and consuming prey; parasitism benefits a parasite while harming its host; mutualism benefits both partners. These relationships can alter survival, reproduction and population size.",highYield:"Compare competition, predation, parasitism and mutualism by their effects."},
      {label:"04 • Form 3",title:"Food chains and webs",body:"A food chain shows one feeding pathway; a food web combines overlapping chains and better represents ecosystem complexity. Arrows point from the organism eaten toward the organism receiving energy. Producers usually capture light energy through photosynthesis, while consumers obtain organic matter by feeding.",highYield:"Read arrows as energy transfer, not as a simple direction of pursuit."},
      {label:"05 • Form 3",title:"Energy flow",body:"Energy enters most ecosystems as sunlight, is stored by producers and passes between trophic levels. At each transfer, energy is used in respiration and dissipated as heat; some also remains in uneaten material or waste. Less energy is therefore available at higher trophic levels, limiting food-chain length and biomass.",highYield:"Energy flows and is dissipated; unlike nutrients, it is not recycled."},
      {label:"06 • Form 3",title:"Population change",body:"Births and immigration add individuals; deaths and emigration remove them. Food supply, disease, predation, competition and weather affect these rates. Populations may grow rapidly when resources are abundant but slow as limiting factors intensify. Carrying capacity is the population size an environment can sustain over time under particular conditions.",highYield:"Population change = births + immigration − deaths − emigration."},
      {label:"07 • Form 3",title:"Nutrient cycling",body:"Bacteria and fungi decompose dead organisms and waste, releasing mineral nutrients that plants can reuse. Elements move between organisms, soil, water and air. Decomposition depends on factors such as temperature, moisture and oxygen; disrupted nutrient availability can reduce ecosystem productivity.",highYield:"Matter is recycled through feeding, waste, death and decomposition."},
      {label:"08 • Form 3",title:"Conservation",body:"Conservation protects species, genetic diversity, habitats and ecosystem processes. Threats include habitat loss, pollution, overharvesting, invasive species and climate change. Strategies include protected areas, habitat restoration, sustainable harvesting, wildlife corridors and community participation. Good decisions consider evidence, livelihoods and long-term resilience.",highYield:"Connect a specific threat to a practical conservation action and explain its effect."}
    ],["Ecology and the Environment"],["ecological","levels","abiotic","factors","biotic","interactions","chains","energy","population","change","nutrient","cycling"],["Core concepts","Applications","Practical interpretation"]),

  lesson("hs-f4-genetics",13,4,"Genetics and Inheritance","Form 4 • Genetics",
    ["Explain genes, alleles, chromosomes and inheritance.","Use simple genetic crosses to predict offspring ratios.","Explain variation and mutation."],
    [
      {label:"01 • Genes",title:"Genes and alleles",body:"A gene is a DNA sequence associated with a functional product or inherited characteristic; alleles are alternative forms of a gene at the same locus. Diploid organisms usually carry two alleles for an autosomal gene, one inherited from each parent. Different alleles can influence a characteristic in different ways.",highYield:"A gene is a DNA region; an allele is a version of that gene."},
      {label:"02 • Chromosomes",title:"Genetic material",body:"DNA stores hereditary information in its nucleotide sequence and is packaged with proteins into chromosomes. Genes are regions of DNA. DNA replication copies information before cell division, while mutations change DNA sequence and can create new alleles. Many mutations have little effect; others may be harmful or beneficial in a particular environment.",highYield:"Relate DNA, genes, chromosomes and inherited information accurately."},
      {label:"03 • Genotype",title:"Genotype and phenotype",body:"Genotype describes the alleles an organism carries; phenotype refers to observable or measurable characteristics produced by genotype interacting with the environment. Nutrition can affect height even when genetic potential is similar. A phenotype alone may not reveal the exact genotype, especially when a dominant allele masks a recessive one.",highYield:"Genotype is genetic constitution; phenotype is the expressed characteristic."},
      {label:"04 • Dominance",title:"Dominant and recessive alleles",body:"In a simple Mendelian model, a dominant allele affects the phenotype of a heterozygote; a recessive allele is expressed only when no dominant allele masks it. Dominance does not mean an allele is more common, stronger or better. State allele symbols clearly before solving a genetic cross.",highYield:"Dominant does not mean common or superior; compare heterozygous and homozygous genotypes."},
      {label:"05 • Crosses",title:"Punnett squares",body:"A Punnett square combines possible gametes to predict offspring genotypes. For Aa × Aa, each parent produces A or a gametes, giving AA, Aa, Aa and aa: an expected 1:2:1 genotype ratio and, under complete dominance, a 3:1 phenotype ratio. These are probabilities, not guarantees for a small family.",highYield:"Write parental genotypes, list gametes, combine alleles and calculate ratios."},
      {label:"06 • Variation",title:"Why individuals differ",body:"Variation may be genetic, environmental or both. Meiosis creates new allele combinations through independent assortment and crossing over; random fertilization also combines alleles. Mutations create new alleles. Environmental factors such as nutrition and temperature affect many traits. Continuous variation forms a range; discontinuous variation falls into distinct categories.",highYield:"Separate inherited variation from environmental influence and identify possible sources."},
      {label:"07 • Sex-linked traits",title:"Inheritance and sex chromosomes",body:"In the usual human chromosome model, most females have XX and most males XY. An ovum normally contributes an X chromosome, while sperm carry X or Y. Other traits are controlled by genes on autosomes or sex chromosomes. This is a simplified school model; biological sex development has additional variation.",highYield:"Use the X/Y sperm model accurately and distinguish sex-linked from autosomal inheritance."},
      {label:"08 • Applications",title:"Genetics in practice",body:"Genetics supports selective breeding, diagnosis of inherited conditions, conservation and biotechnology. Selective breeding can improve desired traits, but a narrow gene pool may reduce diversity and increase inherited problems. Genetic test results need careful interpretation, consent and privacy protections; a risk estimate is not certainty.",highYield:"Evaluate benefits and limitations of a genetic application."}
    ],["Genetics","Cell Biology","Evolution"],["gene","allele","chromosome","DNA","genotype","phenotype","dominant","recessive","mutation","inheritance","variation"],["Genes and alleles","Genotype and phenotype","Genetic crosses","Variation","Sex-linked inheritance"]),

  lesson("hs-f4-evolution",14,4,"Evolution and Adaptation","Form 4 • Evolution",
    ["Explain variation and natural selection.","Describe adaptation and evidence for evolutionary change.","Distinguish natural selection from individual acclimatization."],
    [
      {label:"01 • Variation",title:"Differences in populations",body:"Individuals vary in inherited traits and characteristics shaped by the environment. Continuous variation, such as many measurements of height, spans a range; discontinuous variation falls into distinct categories. Heritable variation provides the material on which natural selection acts.",highYield:"Natural selection requires variation, heritability and differences in reproductive success."},
      {label:"02 • Selection",title:"Natural selection",body:"Individuals with heritable characteristics that improve survival or reproduction in a particular environment tend to leave more offspring. Alleles associated with those traits can become more common over generations. Selection acts on variation; individuals do not develop a needed inherited trait simply because they need it.",highYield:"Explain differential reproductive success across generations, not purposeful change."},
      {label:"03 • Adaptation",title:"Fit to an environment",body:"An adaptation is an inherited feature that improves performance in a particular environment. Structural examples include camouflage; physiological examples include water conservation; behavioural examples include migration. A feature useful in one environment may be less useful in another, so fitness depends on context and reproductive success.",highYield:"Link each adaptation to survival or reproduction in its environment."},
      {label:"04 • Evidence",title:"Evidence for evolution",body:"Evidence includes fossils, anatomical similarities, DNA and protein comparisons, geographical distribution and observed population changes. Homologous structures share an evolutionary origin even when functions differ. Fossils document past life, though the record is incomplete. Multiple independent lines of evidence strengthen evolutionary explanations.",highYield:"Name evidence and explain what it indicates about common ancestry or change."},
      {label:"05 • Resistance",title:"Selection in populations",body:"When environmental pressures differ, individuals with different heritable traits may reproduce at different rates. Over generations, allele frequencies can shift. For example, a resistant microbial variant may survive treatment and multiply while susceptible variants decline. Treatment does not deliberately create a useful trait; selection changes variant frequencies.",highYield:"Explain resistance as selection of heritable variants, not adaptation by choice."},
      {label:"06 • Speciation",title:"Formation of species",body:"Speciation occurs when populations become reproductively isolated and diverge genetically. Geographic barriers can reduce gene flow; mutation, selection and genetic drift then contribute to divergence. If populations can no longer interbreed successfully under the species concept being used, they may be regarded as separate species.",highYield:"Explain isolation, reduced gene flow, divergence and reproductive isolation."},
      {label:"07 • Relatedness",title:"Evolution and classification",body:"Classification increasingly aims to reflect evolutionary history. Shared derived features and DNA similarities help infer common ancestry. A branching evolutionary tree represents a hypothesis about relationships; organisms sharing a more recent common ancestor are generally more closely related.",highYield:"Interpret branches as ancestry hypotheses, not a ladder of progress."},
      {label:"08 • Review",title:"Evolution versus acclimatization",body:"Evolution is a heritable change in populations across generations. Acclimatization is an adjustment by an individual during its lifetime, such as physiological changes after exposure to altitude. Acclimatization does not by itself demonstrate genetic evolution because the adjustment is not necessarily inherited by offspring.",highYield:"Evolution is population-level and heritable; acclimatization is an individual adjustment."}
    ],["Evolution","Genetics"],["evolution","natural selection","adaptation","variation","mutation","speciation","fossil","resistance","selection"],["Variation","Natural selection","Adaptation","Evidence","Speciation"]),

  lesson("hs-f4-ecology",15,4,"Ecology, Population and Conservation","Form 4 • Ecology",
    ["Analyse population changes and ecological relationships.","Explain nutrient cycling and energy transfer.","Evaluate conservation and human impacts on ecosystems."],
    [
      {label:"01 • Population",title:"Population dynamics",body:"Population dynamics studies how population size changes. Birth and death rates, immigration, emigration and resource availability all matter. Exponential growth may occur briefly when resources are abundant; logistic growth slows as limiting factors bring the population toward carrying capacity. Real populations fluctuate with seasons, disease and disturbance.",highYield:"Interpret population curves using resource limits and processes that add or remove individuals."},
      {label:"02 • Sampling",title:"Quadrats and transects",body:"Quadrats estimate abundance or percentage cover for relatively stationary organisms. Random placement reduces sampling bias; replicate samples and means improve reliability. Transects record organisms along a line or belt and can reveal distribution across an environmental gradient. Choose sampling methods and quadrat sizes to suit the organism and habitat.",highYield:"Random sampling reduces bias; replication improves reliability."},
      {label:"03 • Interactions",title:"Competition and predation",body:"Competition occurs when organisms use a shared limited resource; intraspecific competition is within a species and interspecific competition is between species. Predators may reduce prey numbers and alter prey behaviour, while prey availability affects predator populations. These interactions can create linked population changes.",highYield:"Identify the interaction and explain its effects on both populations."},
      {label:"04 • Energy",title:"Trophic levels",body:"A trophic level is an organism's feeding position in a food chain. Producers form the base, primary consumers feed on producers and higher consumers feed on other consumers. Omnivores can occupy more than one level; decomposers process material from all levels and return nutrients.",highYield:"Classify trophic levels from the feeding relationship."},
      {label:"05 • Carbon",title:"Carbon cycling",body:"Photosynthesis removes carbon dioxide from air or water and incorporates carbon into organic molecules. Feeding transfers carbon between organisms; respiration and decomposition release carbon dioxide. Combustion releases carbon stored in biomass or fossil fuels. Deforestation can reduce carbon uptake and release stored carbon.",highYield:"Track carbon through atmosphere, producers, consumers, decomposers and combustion."},
      {label:"06 • Nitrogen",title:"Nitrogen cycling",body:"Most organisms cannot use atmospheric nitrogen gas directly. Nitrogen-fixing bacteria form usable compounds; decomposers release ammonium from organic matter; nitrifying bacteria form nitrites and nitrates. Plants absorb nitrogen compounds to make proteins and nucleic acids, while denitrifying bacteria return nitrogen gas to the atmosphere.",highYield:"Know fixation, ammonification, nitrification, plant uptake and denitrification."},
      {label:"07 • Human impact",title:"Changing ecosystems",body:"Ecosystems change through seasons, succession, disturbance and human activity. Pollution, habitat fragmentation, invasive species and climate change alter species abundance and interactions. After disturbance, pioneer organisms may colonize an area and conditions may change to support a different community. Recovery depends on disturbance severity and continuing pressures.",highYield:"Explain the cause, immediate effects and possible long-term recovery."},
      {label:"08 • Conservation",title:"Sustainable management",body:"Sustainable management uses resources without undermining ecosystem function for future generations. Strategies include regulated harvesting, reforestation, soil and water conservation, pollution reduction, protected areas and monitoring. Effective plans use evidence, enforceable rules and community participation, assessing ecological and social outcomes.",highYield:"Protect long-term ecosystem function rather than maximizing short-term yield."}
    ],["Ecology","Evolution"],["population","sampling","quadrat","transect","competition","predation","energy flow","carbon cycle","nitrogen cycle","conservation","biodiversity"],["Population dynamics","Sampling","Energy flow","Nutrient cycles","Human impact","Conservation"]),

  lesson("hs-f4-applied-biology",16,4,"Applied Biology and Biotechnology","Form 4 • Applied Biology",
    ["Connect biology to agriculture, health and biotechnology.","Explain selected applications of microorganisms and enzymes.","Apply biological principles to practical problems."],
    [
      {label:"01 • Microorganisms",title:"Useful and harmful microbes",body:"Microorganisms include bacteria, fungi, protozoa and microscopic algae; viruses are acellular agents that replicate inside host cells. Useful microbes decompose matter, ferment foods, produce medicines and support nutrient cycles. Pathogens cause disease through damage, toxins or disruption of normal function. Hygiene, vaccination and sanitation reduce different risks.",highYield:"Distinguish bacteria, fungi and viruses and explain both useful roles and disease."},
      {label:"02 • Fermentation",title:"Microbial biotechnology",body:"Microbial biotechnology uses microorganisms or their enzymes to produce useful products. Yeast ferments sugars; selected bacteria make fermented foods and medicines. Industrial processes control temperature, pH, oxygen, nutrients and contamination to maintain yield. Microbes are also used to break down organic waste in treatment systems.",highYield:"Link a microorganism or enzyme to its product and required conditions."},
      {label:"03 • Enzymes",title:"Industrial enzymes",body:"Enzymes are biological catalysts whose active sites bind particular substrates. They are used in detergents, food processing, textiles and diagnostics. Temperature and pH affect reaction rates; extreme conditions may change enzyme structure. Immobilized enzymes can be reused and separated from products more easily.",highYield:"Explain specificity, optimum conditions, denaturation and industrial advantages."},
      {label:"04 • Selective breeding",title:"Improving organisms",body:"Selective breeding chooses parents with desirable inherited traits over generations, but can reduce genetic diversity. Genetic engineering changes or transfers genetic material. Both approaches require assessment of intended benefits, unintended effects, ecological risks, ethics and access.",highYield:"Compare selective breeding with genetic engineering and evaluate benefits and risks."},
      {label:"05 • Tissue culture",title:"Rapid plant propagation",body:"Tissue culture grows plants from small tissue samples under sterile, nutrient-controlled conditions. With suitable growth regulators, tissues can form shoots and roots, rapidly producing many plants. Clones are often genetically similar, so disease or environmental stress may affect many of them; contamination control is essential.",highYield:"Tissue culture is rapid and uniform but requires sterile technique and may reduce variation."},
      {label:"06 • Genetic technology",title:"Using genetic information",body:"Genetic information can support research, screening, diagnosis and treatment decisions. A gene rarely determines a trait alone; environment and interactions with other genes also matter. Screening can indicate risk without guaranteeing an outcome. Consent, confidentiality and qualified interpretation are essential.",highYield:"Distinguish genetic risk from certainty and consider consent and privacy."},
      {label:"07 • Disease control",title:"Biology in public health",body:"Public health biology studies disease spread and ways to reduce population risk. Pathogens may spread through air, contaminated food or water, bodily fluids or vectors. Sanitation, clean water, vaccination, surveillance and vector control target different routes. Antibiotics treat susceptible bacteria, not viruses, and misuse promotes resistance.",highYield:"Match prevention to the transmission route and pathogen."},
      {label:"08 • Review",title:"Applied Biology thinking",body:"Evaluate an applied Biology problem by defining the goal, explaining the mechanism, examining evidence and controls, and assessing unintended consequences. Distinguish correlation from causation and short-term benefit from long-term risk. A strong answer uses evidence and gives a reasoned conclusion rather than listing a technology.",highYield:"Use mechanism, evidence, benefits, limitations and a reasoned conclusion."}
    ],["Applied Biology","Microbiology","Biochemistry"],["biotechnology","microorganism","fermentation","enzyme","selective breeding","tissue culture","pathogen","vaccination","genetic technology"],["Microorganisms","Fermentation","Enzymes","Selective breeding","Tissue culture","Biotechnology"])

];

export function getHighSchoolLesson(id: string) {
  return HIGH_SCHOOL_LESSONS.find(item => item.id === id);
}

export function getVirtualLessonQuestionsMatch(lessonId: string, question: { topic: string; subtopic?: string; prompt: string }) {
  const item = getHighSchoolLesson(lessonId);
  if (!item) return false;
  const haystack = [question.topic, question.subtopic ?? "", question.prompt].join(" ").toLowerCase();
  const topicMatch = item.bankTopics.some(topic => question.topic.toLowerCase().includes(topic.toLowerCase()) || topic.toLowerCase().includes(question.topic.toLowerCase()));
  const keywordHits = item.bankKeywords.filter(keyword => haystack.includes(keyword.toLowerCase())).length;
  return topicMatch || keywordHits >= 1;
}
